 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<1024;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[192]);put(e,U+0x31,1,4|((s&1)!=0?64:0)|((s&2)!=0?8:0));put(e,U+0x64,1,16|((s&4)!=0?8:0));put(e,U+0x8a,1,(s&8)!=0?8:0);put(e,U+0x35,1,15);put(e,U+0x32,2,-777);put(e,U+0x5d,1,7);put(e,U+0x8c,1,9);put(e,U+0x39,1,s%8);put(e,U+0x36,2,0);put(e,0x612f8d,1,0x71);put(e,0x622dd7,1,s*29);for(long a:new long[]{RET,0x452810,0x460910})e.setBreakpoint(toAddr(a));e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,U);int random=0,resumes=0;if(!e.run(toAddr(0x44d6c0),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue();if(pc==0x452810){resumes++;boolean failed=(s&16)!=0;e.writeRegister("EAX",failed?1:0);if(!failed){put(e,U+0x35,1,2);put(e,U+0x32,2,2);}}else if(pc==0x460910){int value=s*1234567+(++random)*32109;e.writeRegister("EAX",value&0xffffffffL);}else throw new Exception("stop");back(e);}out.println("{\"scenario\":"+s+",\"phase\":"+read(e,U+0x35,1)+",\"frame\":"+(short)read(e,U+0x32,2)+",\"flags31\":"+read(e,U+0x31,1)+",\"flags64\":"+read(e,U+0x64,1)+",\"contact5d\":"+read(e,U+0x5d,1)+",\"contact8c\":"+read(e,U+0x8c,1)+",\"object\":"+read(e,0x612f8d,1)+",\"timer\":"+(byte)read(e,U+0x3c,1)+",\"search\":"+read(e,U+0x7d,1)+",\"random\":"+random+",\"resumes\":"+resumes+"}");}finally{e.dispose();}}}}
